  "pdp.shipping.body": "$69 이상 주문 시 무료 추적 배송($69 미만은 고정 배송비 $9.9). 렌즈 가공을 포함해 국가에 따라 7–30일 내 배송됩니다. 무도수 안경은 30일 무료 반품·교환. 도수 안경은 처방과 PD에 맞춰 제작되므로 제조 결함이나 처방 오류가 아닌 경우 반품·교환이 불가합니다.",
