  "pdp.details.body":
    "Chế tác từ chất liệu cao cấp, chú trọng từng chi tiết. Bề mặt đánh bóng thủ công, đệm mũi không gây kích ứng, càng kính bản lề lò xo cho cảm giác đeo cả ngày.",
  "pdp.desc.body":
    "Gọng kính siêu nhẹ thiết kế cho những ngày dài. Acetate đánh bóng thủ công, đệm mũi an toàn cho da và càng kính có lò xo cho cảm giác đeo nhẹ tênh. Kết hợp với tròng cao cấp của chúng tôi để có tầm nhìn sắc nét, không loá.",
