  "pdp.specs.gender": "Giới tính",
  "pdp.specs.unisex": "Unisex",
  "pdp.lens.body":
    "Chọn giữa tròng đơn tròng, lọc ánh sáng xanh hoặc đa tròng. Tất cả đều có chống xước và chống tia UV400 tiêu chuẩn. Nâng cấp lên tròng chiết suất 1.61 hoặc 1.67 để mỏng nhẹ hơn.",
  "pdp.lens.feat.blue.title": "Lọc ánh sáng xanh",
  "pdp.lens.feat.blue.desc":
    "Giảm mỏi mắt và bảo vệ khỏi ánh sáng xanh có hại từ màn hình và thiết bị điện tử.",
  "pdp.lens.feat.photo.title": "Đổi màu",
  "pdp.lens.feat.photo.desc":
    "Tự động đậm hơn ngoài trời, nhạt lại trong nhà — thoải mái cả ngày.",
  "pdp.lens.feat.polar.title": "Phân cực",
  "pdp.lens.feat.polar.desc":
    "Chặn loá từ bề mặt phản chiếu, tăng độ rõ và giảm mỏi mắt.",
  "pdp.lens.feat.driving.title": "Lái xe",
  "pdp.lens.feat.driving.desc":
    "Giảm loá và tăng độ tương phản cho tầm nhìn rõ ràng, an toàn hơn trên đường.",
  "pdp.lens.feat.tinted.title": "Nhuộm màu",
  "pdp.lens.feat.tinted.desc":
    "Tăng độ tương phản và giảm loá, mang lại sự thoải mái và rõ ràng trong nhiều điều kiện ánh sáng.",
  "pdp.desc.measureTitle": "Số đo gọng",
  "pdp.shipping.body": "Miễn phí vận chuyển có theo dõi cho đơn trên $69 (dưới $69 phí cố định $9.9). Giao hàng 7–30 ngày tùy quốc gia, đã gồm thời gian gia công tròng. Đổi trả miễn phí 30 ngày với kính không độ. Kính có độ được làm riêng theo đơn kính và PD của bạn, không đổi trả trừ khi lỗi sản xuất hoặc sai độ.",
  "pdp.reviews.write": "Viết đánh giá",
