  "pdp.details.body":
    "Dibina daripada bahan premium dengan perhatian kepada setiap butiran. Permukaan digilap tangan, pelapik hidung hipoalergenik, dan tangkai berengsel spring untuk kesesuaian halus sepanjang hari.",
  "pdp.desc.body":
    "Bingkai ringan direka untuk hari yang panjang. Asetat digilap tangan, pelapik hidung hipoalergenik, dan tangkai berengsel spring untuk kesesuaian yang ringan. Padankan dengan kanta premium kami untuk penglihatan yang jelas dan bebas silau.",
  "pdp.specs.frameMaterial": "Bahan bingkai",
  "pdp.specs.shape": "Bentuk",
  "pdp.specs.style": "Gaya",
  "pdp.specs.weight": "Berat",
  "pdp.specs.gender": "Jantina",
  "pdp.specs.unisex": "Uniseks",
  "pdp.lens.body":
    "Pilih antara kanta penglihatan tunggal, cahaya biru atau progresif. Semua dilengkapi dengan perlindungan tahan calar dan UV400 standard. Naik taraf ke kanta indeks tinggi 1.61 atau 1.67 untuk tampilan yang lebih nipis dan ringan.",
  "pdp.lens.feat.blue.title": "Penyekat cahaya biru",
  "pdp.lens.feat.blue.desc":
    "Mengurangkan ketegangan mata dan melindungi daripada cahaya biru berbahaya dari skrin dan peranti digital.",
  "pdp.lens.feat.photo.title": "Fotokromik",
  "pdp.lens.feat.photo.desc":
    "Menyesuaikan diri secara automatik dengan cahaya, gelap di luar dan terang di dalam untuk keselesaan sepanjang hari.",
  "pdp.lens.feat.polar.title": "Berpolarisasi",
  "pdp.lens.feat.polar.desc":
    "Menyekat silau daripada permukaan reflektif, meningkatkan kejelasan dan mengurangkan keletihan mata.",
  "pdp.lens.feat.driving.title": "Memandu",
  "pdp.lens.feat.driving.desc":
    "Mengurangkan silau dan meningkatkan kontras untuk penglihatan yang lebih jelas dan selamat di jalan raya.",
  "pdp.lens.feat.tinted.title": "Berwarna",
  "pdp.lens.feat.tinted.desc":
    "Meningkatkan kontras dan mengurangkan silau, menawarkan keselesaan dan kejelasan yang lebih baik dalam pelbagai keadaan cahaya.",
  "pdp.desc.measureTitle": "Ukuran bingkai",
  "pdp.shipping.body": "Penghantaran percuma dengan penjejakan untuk pesanan melebihi $69 (bawah $69 yuran tetap $9.9). Penghantaran 7–30 hari bergantung pada negara, termasuk pemprosesan kanta. Pemulangan & pertukaran percuma 30 hari untuk cermin mata tanpa preskripsi. Cermin mata preskripsi dibuat khas mengikut preskripsi dan PD anda dan tidak boleh dipulangkan kecuali kecacatan pembuatan atau ralat preskripsi.",
  "pdp.reviews.write": "Tulis ulasan",
