// Lowercase index of COLOR_NAMES so localizeColorName tolerates the
// "BLACK" / "Black" / "black" casing variance in D1's label_json.
const COLOR_NAMES_LC: Record<
  string,
  Partial<Record<Lang, string>>
> = Object.fromEntries(
  Object.entries(COLOR_NAMES).map(([k, v]) => [k.toLowerCase(), v]),
);

/* ---------- Provider ---------- */

interface I18nCtx {
  lang: Lang;
  contentLang: ContentLang;
  setLang: (l: Lang) => void;
  t: (key: Key) => string;
  /** Returns the product name in the active UI language, or English fallback. */
  localizeProductName: (slug: string, fallback?: string) => string;
  /**
   * Returns the localized name for a frame-color label, looked up by its
   * canonical English string (the same one stored in product_colors.label_json.en).
   * Falls back to the second argument when no mapping exists.
   */
  localizeColorName: (enName: string, fallback?: string) => string;
  languages: LangMeta[];
  /** True once the user has explicitly picked a language. AI GEO must respect this. */
  userPicked: boolean;
}

const Ctx = createContext<I18nCtx | null>(null);

const STORAGE_KEY = "lool-lang";
const PICKED_KEY = "lool-lang-picked";

/** Codes of all supported languages — used by URL parser + sitemap + hreflang. */
export const SUPPORTED_LANG_CODES: readonly Lang[] = LANGUAGES.map(
  (l) => l.code,
);

function isSupportedLang(s: string): s is Lang {
  return (SUPPORTED_LANG_CODES as readonly string[]).includes(s);
}

/** Extract the language code from a URL pathname.
 * Returns the lang if the first path segment is one of the 10 supported codes,
 * else null (e.g. for /admin, /api, /sitemap.xml). */
export function langFromPath(pathname: string): Lang | null {
  const seg = pathname.split("/").filter(Boolean)[0];
  return seg && isSupportedLang(seg) ? seg : null;
}

/** Translate a single dict key without going through the I18nProvider context.
 * Use for components that may render outside the provider — e.g. router-level
 * error boundaries that catch errors before `RootComponent` mounts, or admin
 * pages that intentionally skip the customer I18nProvider. Same fallback
 * semantics as the in-context `t` (current lang → en → key). */
export type TranslationKey = keyof typeof en;
export function getTranslator(lang: Lang): (key: TranslationKey) => string {
  return (key) => dict[lang][key] ?? en[key] ?? key;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const router = useRouter();
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const urlLang = langFromPath(pathname);

  const [storedLang, setStoredLang] = useState<Lang>("en");
  const [userPicked, setUserPicked] = useState<boolean>(false);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const saved = localStorage.getItem(STORAGE_KEY) as Lang | null;
    if (saved && dict[saved]) {
      setStoredLang(saved);
    }
    setUserPicked(localStorage.getItem(PICKED_KEY) === "1");
  }, []);

  // URL is canonical when present; localStorage is fallback (admin pages,
  // direct-link landing before hydration, transient routes without $lang).
  const lang: Lang = urlLang ?? storedLang;

  // sync html lang + dir
  useEffect(() => {
    if (typeof document === "undefined") return;
    document.documentElement.lang = lang;
    const meta = LANGUAGES.find((l) => l.code === lang);
    document.documentElement.dir = meta?.dir ?? "ltr";
  }, [lang]);

  const setLang = (l: Lang) => {
    if (l === lang) return;
    setStoredLang(l);
    setUserPicked(true);
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, l);
      localStorage.setItem(PICKED_KEY, "1");
      // Server reads this cookie in /$.tsx to honor the user's pick when
      // they revisit the bare domain. SameSite=Lax + Secure (HTTPS in prod).
      const secure = window.location.protocol === "https:" ? "; Secure" : "";
      document.cookie = `${STORAGE_KEY}=${encodeURIComponent(l)}; Path=/; Max-Age=31536000; SameSite=Lax${secure}`;
    }
    // If we're on a $lang URL, navigate to the equivalent path with new lang.
    // Otherwise we're on an unprefixed route (admin/api etc.) — just update
    // localStorage so the next $lang page picks up the preference.
    if (urlLang) {
      const newPath = pathname.replace(/^\/[a-z]{2}(?=\/|$)/, `/${l}`);
      router.navigate({ to: newPath, replace: true });
    }
    // Localized success toast — message itself uses the *new* language.
    const meta = LANGUAGES.find((m) => m.code === l);
    const template = (dict[l]["lang.switched"] ??
      en["lang.switched"]) as string;
    toast.success(template.replace("{lang}", meta?.label ?? l.toUpperCase()));
  };

  const t = (key: Key) => dict[lang][key] ?? en[key] ?? key;
  const contentLang: ContentLang = lang;
  const localizeProductName = (slug: string, fallback?: string) => {
    const entry = PRODUCT_NAMES[slug];
    return (entry && (entry[lang] ?? fallback ?? entry.en)) ?? fallback ?? slug;
  };
  const localizeColorName = (enName: string, fallback?: string) => {
    // Try exact key first (back-compat for design-mockup colors like
    // "Matte Black" / "Champagne Gold" stored with original casing), then
    // fall back to the lowercase index so D1's mixed casing (BLACK / Black
    // / black) still resolves.
    const entry =
      COLOR_NAMES[enName] ?? COLOR_NAMES_LC[enName?.toLowerCase() ?? ""];
    return (entry && (entry[lang] ?? entry.en)) ?? fallback ?? enName;
  };

  return (
    <Ctx.Provider
      value={{
        lang,
        contentLang,
        setLang,
        t,
        localizeProductName,
        localizeColorName,
        languages: LANGUAGES,
        userPicked,
      }}
    >
      {children}
    </Ctx.Provider>
  );
}

export function useI18n() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useI18n must be used within I18nProvider");
  return ctx;
}

/** Non-throwing variant — returns null when the caller renders outside an
 * I18nProvider (e.g. inside /admin or /tracker, which intentionally skip the
 * customer provider). Components that want to work in both contexts should
 * use this + getTranslator() rather than useI18n. */
export function useI18nOptional() {
  return useContext(Ctx);
}

// shape / material come from D1 as canonical English slugs (round, square,
// tr90, titanium …). Map slug → existing menu.shape.* / menu.material.* i18n
// key (fully translated for 14 langs by the nav mega menu) and fall back to
// the raw value if a new slug appears that the i18n dict hasn't caught up to.
type TFn = (key: Key) => string;
const SHAPE_KEY_MAP: Partial<Record<string, Key>> = {
  round: "menu.shape.round",
  square: "menu.shape.square",
  rectangle: "menu.shape.rectangle",
  aviator: "menu.shape.aviator",
  cateye: "menu.shape.cateye",
  butterfly: "menu.shape.butterfly",
  browline: "menu.shape.browline",
  geometric: "menu.shape.geometric",
  oval: "menu.shape.oval",
};
const MATERIAL_KEY_MAP: Partial<Record<string, Key>> = {
  acetate: "menu.material.acetate",
  metal: "menu.material.metal",
  tr90: "menu.material.tr90",
  titanium: "menu.material.titanium",
};
export function shapeLabel(shape: string | null | undefined, t: TFn): string {
  if (!shape) return "";
  const k = SHAPE_KEY_MAP[shape.toLowerCase().replace(/[\s-]+/g, "")];
  return k ? t(k) : shape;
}
export function materialLabel(
  material: string | null | undefined,
  t: TFn,
): string {
  if (!material) return "";
  const k = MATERIAL_KEY_MAP[material.toLowerCase().replace(/[\s-]+/g, "")];
  return k ? t(k) : material.toUpperCase();
}
